package bo.edu.uagrm.saludu.agenda.api;
import bo.edu.uagrm.saludu.agenda.application.AvailabilityException;import bo.edu.uagrm.saludu.identity.infrastructure.SessionPrincipal;import bo.edu.uagrm.saludu.shared.persistence.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/medical/encounters") public class EncounterAmendmentController {private final JdbcTemplate j;private final DatabaseActorContext c;public EncounterAmendmentController(JdbcTemplate j,DatabaseActorContext c){this.j=j;this.c=c;}@PostMapping("/{id}/amendments") @PreAuthorize("hasAnyRole('REVIEW_DOCTOR','SPECIALIST')") @Transactional public LegacyAvailabilityResponse<Map<String,Object>> add(@PathVariable UUID id,@RequestBody Map<String,Object>b,@AuthenticationPrincipal SessionPrincipal p){String reason=b.get("reason") instanceof String s?s:null,content=b.get("content") instanceof String s?s:null;if(reason==null||content==null)throw new AvailabilityException(400,"El motivo y contenido de la adenda son obligatorios.");c.apply(new DatabaseActor(p.id(),Set.copyOf(p.roles())));try{return LegacyAvailabilityResponse.success(j.queryForObject("select * from salud_u.agregar_adenda_encuentro(?,?,?)",(r,n)->Map.of("id",r.getObject("id",UUID.class),"amendmentNo",r.getInt("numero_adenda"),"createdAt",r.getObject("creada_en"),"createdBy",r.getObject("creada_por",UUID.class)),id,reason,content));}catch(org.springframework.dao.DataAccessException e){throw new AvailabilityException(403,"No se puede agregar una adenda a esta atención.");}}}
